def get_all_subclasses(cls):
    """**Deprecated**: Use ansible.module_utils.common._utils.get_all_subclasses instead"""
    return list(_get_all_subclasses(cls))


# End compat shims


def _no_log_container_kind(value):
    if isinstance(value, Mapping):
        return 'mapping'
    if isinstance(value, (text_type, binary_type)):
        return None
    if isinstance(value, Sequence):
        return 'sequence'
    if isinstance(value, Set):
        return 'set'
    return None


def _no_log_pattern(no_log_strings):
    # Longest matches take precedence, independent of the iterable's order.
    strings = frozenset(to_native(s, errors='surrogate_or_strict') for s in no_log_strings)
    strings = frozenset(s for s in strings if s)
    if not strings:
        return strings, None
    ordered = sorted(strings, key=lambda s: (-len(s), s))
    return strings, re.compile('|'.join(re.escape(s) for s in ordered))


def _mask_no_log_string(value, pattern):
    if pattern is None or not isinstance(value, (text_type, binary_type)):
        return value
    masked = pattern.sub('********', to_native(value, errors='surrogate_or_strict'))
    if isinstance(value, binary_type) and PY3:
        return to_bytes(masked, errors='surrogate_or_strict')
    if isinstance(value, text_type) and PY2:
        return to_text(masked, errors='surrogate_or_strict')
    return masked


def _empty_no_log_container(value):
    try:
        new_value = copy.copy(value)
        if new_value is value:
            raise TypeError('copy returned the original container')
        new_value.clear()
    except (AttributeError, TypeError):
        new_value = type(value)()
    return new_value


def _immutable_no_log_container(value, kind, elements):
    if kind == 'mapping':
        pairs = list(elements)
        try:
            return type(value)(pairs)
        except TypeError:
            return type(value)(dict(pairs))
    if kind == 'set':
        if isinstance(value, KeysView):
            return dict.fromkeys(elements).keys()
        return type(value)(elements)
    if isinstance(value, tuple) and hasattr(type(value), '_fields'):
        return type(value)(*elements)
    if hasattr(value, 'start') and hasattr(value, 'stop') and hasattr(value, 'step'):
        return type(value)(value.start, value.stop, value.step)
    return type(value)(elements)


def _transform_no_log(value, no_log_strings, keys_only, ignore_keys):
    strings, pattern = _no_log_pattern(no_log_strings)
    ignored = frozenset(to_native(k, errors='surrogate_or_strict') for k in ignore_keys)

    def redact_key(key):
        if not isinstance(key, (text_type, binary_type)):
            return key
        native_key = to_native(key, errors='surrogate_or_strict')
        if native_key in ignored or native_key.startswith('_ansible'):
            return key
        if native_key in strings:
            return 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
        return _mask_no_log_string(key, pattern)

    # Discover the container graph without using the Python call stack.
    nodes = {}
    parents = {}
    pending = [value]
    while pending:
        current = pending.pop()
        kind = _no_log_container_kind(current)
        if kind is None or id(current) in nodes:
            continue
        children = list(current.values()) if kind == 'mapping' else list(current)
        nodes[id(current)] = (current, kind, children)
        for child in children:
            if _no_log_container_kind(child) is not None:
                parents.setdefault(id(child), set()).add(id(current))
                pending.append(child)

    if not nodes:
        return value if keys_only else _mask_no_log_string(value, pattern)

    # A sequence or set only needs copying when it contains a mapping.
    affected = set(nodes) if not keys_only else set(
        node_id for node_id, node in nodes.items() if node[1] == 'mapping'
    )
    if keys_only:
        queue = deque(affected)
        while queue:
            for parent_id in parents.get(queue.popleft(), ()):
                if parent_id not in affected:
                    affected.add(parent_id)
                    queue.append(parent_id)
        if id(value) not in affected:
            return value

    def is_mutable(node):
        old, kind, unused_children = node
        return ((kind == 'mapping' and isinstance(old, MutableMapping)) or
                (kind == 'sequence' and isinstance(old, MutableSequence)) or
                (kind == 'set' and isinstance(old, MutableSet)))

    results = {}
    for node_id in affected:
