    def test_handles_deep_mapping_nesting(self):
        original = {}
        child = original
        for unused in range(2000):
            nested = {}
            child['next'] = nested
            child = nested
        child['api-password'] = 'raw'

        child = sanitize_keys(original, ('password',))
        for unused in range(2000):
            child = child['next']
        self.assertEqual(child, {'api-********': 'raw'})

